def subtract(a, b):
    # Filter out empty intervals
    a = [[start, end] for start, end in a if start < end]
    b = [[start, end] for start, end in b if start < end]

    if not a:
        return []

    # Merge overlapping intervals in a
    a_sorted = sorted(a)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_sorted = sorted(b)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort result by start position
    result.sort()

    # Merge adjacent intervals
    if not result:
        return []

    merged = [result[0]]
    for start, end in result[1:]:
        if start == merged[-1][1]:
            merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

